// READ-ONLY CONNECTOR. Reads your project from the pmd_project, pmd_tasks and pmd_milestones tables.
// Fill them from your inputs (see inputs/README.md in the repo). While those tables are empty,
// the fictional sample below is used, so the demo works straight after install.
// Rows are never deleted: each load gets a new "batch" stamp and only the latest batch is used.
const fromTable = (n) => $(n).all().map(i => i.json).filter(r => r && r.id);
const latest = (rows) => { const b = rows.map(r => String(r.batch || '')).sort().pop(); return rows.filter(r => String(r.batch || '') === b); };
const tblProject = latest(fromTable('Read Project')).pop() || {};
const tblTasks = latest(fromTable('Read Tasks'));
const tblMilestones = latest(fromTable('Read Milestones'));
const yes = (v) => /^(y|yes|true|1)$/i.test(String(v ?? '').trim());
const num = (v) => Number(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0;
const iso = (v) => String(v ?? '').trim().slice(0, 10);
if (tblTasks.length && tblMilestones.length) {
  const tasks = tblTasks.map(r => ({ id: r.task_id, task: r.task, owner: r.owner, workstream: r.workstream || '', due: iso(r.due), progress: num(r.progress), status: r.status, critical: yes(r.critical), blocker: r.blocker || '', milestone: r.milestone || '' }));
  const milestones = tblMilestones.map(r => ({ name: r.name, baseline: iso(r.baseline), forecast: iso(r.forecast), dependsOn: r.depends_on || null, status: r.status || '' }));
  const t0 = new Date(); t0.setHours(0, 0, 0, 0);
  const teamNotes = String(tblProject.team_notes || '').split(/\n|\|/).map(s => s.trim()).filter(Boolean);
  return [{ json: {
    reportDate: t0.toISOString().slice(0, 10),
    project: { name: tblProject.name || 'My project', sponsor: tblProject.sponsor || '', phase: tblProject.phase || '', budgetPlanned: num(tblProject.budget_planned), budgetSpent: num(tblProject.budget_spent), goLive: iso(tblProject.go_live) },
    tasks, milestones, teamNotes
  } }];
}

// ---- Fictional sample, used only while the tables are empty ----
const today = new Date();
today.setHours(0, 0, 0, 0);
const d = (n) => { const x = new Date(today); x.setDate(x.getDate() + n); return x.toISOString().slice(0, 10); };

const project = {
  name: 'Project Atlas: CRM Migration',
  sponsor: 'VP Sales Operations',
  phase: 'Build',
  budgetPlanned: 250000,
  budgetSpent: 171000,
  goLive: d(47)
