const milestones = [
  { name: 'Data migration dry run', baseline: d(5), forecast: d(12) },
  { name: 'UAT start', baseline: d(19), forecast: d(21) },
  { name: 'Go-live', baseline: d(47), forecast: d(47) }
];

const teamNotes = [
  'Billing vendor says sandbox credentials will arrive early next week, no firm date.',
  'Two UAT testers are shared with the Q4 audit and may be unavailable for 5 days.',
  'Sales leadership asked for a training demo before go-live.',
  'Reporting dashboards finished a day early.'
];

return [{ json: { reportDate: d(0), project, tasks, milestones, teamNotes } }];

// RAG status is set by fixed rules here, NOT by the AI.
// The rules are visible and auditable; the AI only writes the narrative.
const data = $input.first().json;
const today = new Date(data.reportDate);
const DAY = 86400000;

const open = data.tasks.filter(t => t.status !== 'Done');
const done = data.tasks.filter(t => t.status === 'Done');
const overdue = open.filter(t => new Date(t.due) < today);
const blocked = open.filter(t => t.status === 'Blocked');
const dueNext7 = open.filter(t => { const days = (new Date(t.due) - today) / DAY; return days >= 0 && days <= 7; });
const criticalOverdue = overdue.filter(t => t.critical);

const percentComplete = Math.round(data.tasks.reduce((s, t) => s + t.progress, 0) / data.tasks.length);
const budgetUsedPct = Math.round((data.project.budgetSpent / data.project.budgetPlanned) * 100);

const milestones = data.milestones.map(m => ({ ...m, slipDays: Math.round((new Date(m.forecast) - new Date(m.baseline)) / DAY) }));
// A finished milestone's old slip is history: it is still reported, but it no longer sets the RAG.
const isDone = (m) => String(m.status || '').trim().toLowerCase() === 'done';
const maxSlip = Math.max(0, ...milestones.filter(m => !isDone(m)).map(m => m.slipDays));

const reasons = [];
if (maxSlip > 0) reasons.push('Milestone slip of up to ' + maxSlip + ' days');
if (criticalOverdue.length) reasons.push(criticalOverdue.length + ' critical task(s) overdue');
if (overdue.length > criticalOverdue.length) reasons.push((overdue.length - criticalOverdue.length) + ' non-critical task(s) overdue');
if (blocked.length) reasons.push(blocked.length + ' task(s) blocked');
if (budgetUsedPct - percentComplete > 10) reasons.push('Budget burn (' + budgetUsedPct + '%) ahead of progress (' + percentComplete + '%)');

let rag = 'Green';
if (maxSlip > 5 || criticalOverdue.length >= 2) rag = 'Red';
else if (reasons.length) rag = 'Amber';

return [{ json: {
  ...data,
  metrics: {
    rag,
    ragReasons: reasons.length ? reasons : ['On track: no slips, overdue or blocked work'],
    percentComplete,
    budgetUsedPct,
    tasksDone: done.length,
    tasksOpen: open.length,
    overdue: overdue.map(t => ({ id: t.id, task: t.task, owner: t.owner, due: t.due, critical: t.critical })),
    blocked: blocked.map(t => ({ id: t.id, task: t.task, owner: t.owner, blocker: t.blocker })),
    dueNext7: dueNext7.map(t => ({ id: t.id, task: t.task, owner: t.owner, due: t.due })),
    milestones
  }
} }];

// Email layout helpers: full width, left aligned, table-based so Outlook renders it consistently.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const F = 'font-family:Segoe UI,Arial,Helvetica,sans-serif;color:#1f2937;';
const T = (t, sub) => '<p style="' + F + 'margin:0 0 4px 0;font-size:20px;font-weight:700;line-height:1.3">' + t + '</p>' + (sub ? '<p style="' + F + 'margin:0 0 14px 0;font-size:13px;color:#6b7280">' + sub + '</p>' : '');
const H = (t) => '<p style="' + F + 'margin:20px 0 8px 0;font-size:15px;font-weight:700">' + t + '</p>';
const P = (t) => '<p style="' + F + 'margin:0 0 10px 0;font-size:14px;line-height:1.5">' + t + '</p>';
const UL = (a) => (a && a.length) ? '<ul style="' + F + 'margin:0 0 10px 0;padding:0 0 0 20px;font-size:14px;line-height:1.5">' + a.map(x => '<li style="margin:0 0 4px 0">' + esc(x) + '</li>').join('') + '</ul>' : P('<em>None</em>');
const CELL = F + 'border:1px solid #d1d5db;padding:6px 8px;text-align:left;vertical-align:top;font-size:13px;line-height:1.4;';
const TBL = (head, rows) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 10px 0">' + (head ? '<tr>' + head.map(h => '<th style="' + CELL + 'background:#f3f4f6;font-weight:700">' + h + '</th>').join('') + '</tr>' : '') + rows.map(r => '<tr>' + r.map(c => '<td style="' + CELL + '">' + c + '</td>').join('') + '</tr>').join('') + '</table>';
const BOX = (t, line, bg) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 12px 0"><tr><td style="' + F + 'background:' + bg + ';border-left:4px solid ' + line + ';padding:10px 12px;font-size:14px;line-height:1.5">' + t + '</td></tr></table>';
const PILL = (t, bg) => '<span style="background:' + bg + ';color:#ffffff;padding:2px 10px;border-radius:10px;font-weight:700;font-size:12px">' + t + '</span>';
const BTN = '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:16px 0"><tr><td style="background:#1f4e79;border-radius:4px"><a href="%%DECIDE_URL%%" style="' + F + 'display:inline-block;padding:11px 22px;color:#ffffff;font-size:14px;font-weight:700;text-decoration:none">Review and decide</a></td></tr></table>';
const NOTE = (t) => '<p style="' + F + 'margin:16px 0 0 0;font-size:12px;line-height:1.5;color:#6b7280">' + t + '</p>';
const WRAP = (inner) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse"><tr><td style="' + F + 'padding:0;text-align:left">' + inner + '</td></tr></table>';
const RAG = { Green: '#1e7e34', Amber: '#b26a00', Red: '#b00020' };
const r = $input.first().json.output;
const src = $('Calculate Health and RAG').first().json;
const m = src.metrics;
const ms = m.milestones.map(x => [esc(x.name), x.baseline, x.forecast, x.slipDays > 0 ? '<b style="color:#b00020">+' + x.slipDays + ' days</b>' : 'On time']);
const risks = (r.risks || []).map(x => [esc(x.risk), esc(x.impact), esc(x.mitigation), esc(x.owner)]);
const body = BOX('Draft prepared by the Weekly Status Agent. Review and edit before sending.', '#b26a00', '#fff8e1')
  + T(esc(src.project.name), 'Week ending ' + src.reportDate + ' · Phase: ' + esc(src.project.phase) + ' · Sponsor: ' + esc(src.project.sponsor))
  + BOX(PILL(m.rag.toUpperCase(), RAG[m.rag]) + '&nbsp;&nbsp;' + m.percentComplete + '% complete · ' + m.budgetUsedPct + '% of budget used · ' + m.tasksOpen + ' open tasks<br><span style="font-size:13px;color:#4b5563">Why ' + m.rag + ': ' + m.ragReasons.map(esc).join('; ') + '</span>', RAG[m.rag], '#f9fafb')
  + H('Summary') + P(esc(r.executiveSummary))
  + H('Milestones') + TBL(['Milestone', 'Baseline', 'Forecast', 'Slip'], ms)
  + H('Done this week') + UL(r.accomplishments)
  + H('Next week') + UL(r.nextWeek)
  + H('Risks and issues') + (risks.length ? TBL(['Risk', 'Impact', 'Mitigation', 'Owner'], risks) : P('<em>None</em>'))
  + H('Decisions needed') + UL(r.decisionsNeeded);
return [{ json: { subject: r.subject, html: WRAP(body), rag: m.rag } }];
